local a={}local b={}local c=0;local d=500;local e={DEBUG=true,INFO=true,WARN=true,ERROR=true}function a.write(f,g,h)f=tostring(f or"INFO"):upper()if not e[f]then f="INFO"end;c=c+1;b[#b+1]={id=c,timestamp=os.epoch("utc"),level=f,source=tostring(g or"system"),content=tostring(h or"")}while#b>d do table.remove(b,1)end end;function a.getEntries(i)local j={}local k=math.max(1,#b-(i or#b)+1)for l=#b,k,-1 do local m={}for n,o in pairs(b[l])do m[n]=o end;j[#j+1]=m end;return j end;function a.new(g)g=tostring(g or"system")local p={}for f in pairs(e)do local q=f;local r=q:lower()p[r]=function(h)a.write(q,g,h)end end;return p end;return a
